script:
test("inclusive end date on the last day of April is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-30"
  }), { covered: true, remaining: 1 });
});

test("one day after the end date is not covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-05-01"
  }), { covered: false, remaining: 2 });
});

test("used equals approved so a middle date is not covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  }), { covered: false, remaining: 0 });
});

test("inclusive start on the first of February is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-01"
  }), { covered: true, remaining: 1 });
});

test("one day before the start on the last day of January is not covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-01-31"
  }), { covered: false, remaining: 2 });
});

test("January 1 after a December 31 start is covered and leaves 4", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 2,
    startDate: "2025-12-31",
    endDate: "2026-01-31",
    visitDate: "2026-01-01"
  }), { covered: true, remaining: 4 });
});

test("one day before a leap day end is covered and leaves 7", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 11,
    usedVisits: 3,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-02-28"
  }), { covered: true, remaining: 7 });
});

test("the last remaining visit in the middle of March is covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 4,
    startDate: "2026-03-01",
    endDate: "2026-03-31",
    visitDate: "2026-03-16"
  }), { covered: true, remaining: 0 });
});

test("one step under the last visit threshold is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 3,
    startDate: "2026-03-01",
    endDate: "2026-03-31",
    visitDate: "2026-03-02"
  }), { covered: true, remaining: 1 });
});

test("zero approved and zero used so an in range visit is not covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: "2026-08-01",
    endDate: "2026-08-31",
    visitDate: "2026-08-15"
  }), { covered: false, remaining: 0 });
});

test("a single day January 1 window is covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-01-01",
    endDate: "2026-01-01",
    visitDate: "2026-01-01"
  }), { covered: true, remaining: 0 });
});

test("a visit on December 31 before a single day January 1 window is not covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-01-01",
    endDate: "2026-01-01",
    visitDate: "2025-12-31"
  }), { covered: false, remaining: 1 });
});

test("December 1 inclusive start is covered and leaves 8", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 9,
    usedVisits: 0,
    startDate: "2025-12-01",
    endDate: "2026-01-31",
    visitDate: "2025-12-01"
  }), { covered: true, remaining: 8 });
});

test("leap day as an inclusive end date is covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-02-29"
  }), { covered: true, remaining: 2 });
});

test("one day after leap day is not covered and leaves 3", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-03-01"
  }), { covered: false, remaining: 3 });
});

test("an unknown comment field throws unknown field comment", function () {
  assert.throws(function () {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 1,
      startDate: "2026-03-01",
      endDate: "2026-03-31",
      visitDate: "2026-03-10",
      comment: "note"
    });
  }, /^unknown field: comment$/);
});
